}

label[for="agree-terms"] a:hover {
    color: #93c5fd;
}

label[for="agree-terms"] a:focus {
    outline: 2px solid #3b82f6;
    outline-offset: 2px;
    border-radius: 2px;
}

.required-marker {
    color: #ef4444;
    font-weight: 600;
    margin-left: 2px;
}

.helper-text {
    font-size: 14px;
